const c="0123456789ABCDEFGHJKMNPQRSTVWXYZ",i=c+"*~$=U";export const KEY_BYTES=15,KEY_SYMBOLS=24,DESTROY_DOMAIN="tessera-destroy-v1:",COMMITMENT_BYTES=15;export function normalize(t){return String(t).toUpperCase().replace(/[\s-]/g,"").replace(/[IL]/g,"1").replace(/O/g,"0")}export function encode(t){let e=0,o=0,r="";for(const n of t)for(e=e<<8|n,o+=8;o>=5;)o-=5,r+=c[e>>>o&31];return r}export function decode(t){let e=0,o=0;const r=[];for(const n of t){const s=c.indexOf(n);if(s<0)throw new Error("crockford: invalid symbol");e=e<<5|s,o+=5,o>=8&&(o-=8,r.push(e>>>o&255))}return new Uint8Array(r)}export function checkSymbol(t){let e=0;for(const o of t)e=(e*256+o)%37;return i[e]}export function format(t){return t.match(/.{1,5}/g).join("-")}export function isValid(t){const e=normalize(t);if(e.length!==KEY_SYMBOLS+1)return!1;try{return checkSymbol(decode(e.slice(0,KEY_SYMBOLS)))===e[KEY_SYMBOLS]}catch{return!1}}export function generateKey(){if(typeof crypto>"u"||typeof crypto.getRandomValues!="function")throw new Error("crockford: no CSPRNG available, refusing to generate a key");const t=crypto.getRandomValues(new Uint8Array(KEY_BYTES));return format(encode(t)+checkSymbol(t))}export async function commitment(t){if(typeof crypto>"u"||!crypto.subtle)throw new Error("crockford: crypto.subtle unavailable (needs a secure context)");const e=new TextEncoder().encode(DESTROY_DOMAIN+normalize(t)),o=await crypto.subtle.digest("SHA-256",e);return new Uint8Array(o).slice(0,COMMITMENT_BYTES)}
